-- Sample data so the site looks alive without the chip running.
-- Safe to re-run: clears its own demo rows first, then re-inserts.
-- Apply with:  psql soil_monitor -f seed.sql

-- Start clean (CASCADE clears readings + waterings via FK).
DELETE FROM plants WHERE name IN ('Bladverk Calathea', 'Fönster Monstera');

-- Care info (normally auto-generated by Groq; written here so the care cards
-- render without needing an API call).
INSERT INTO plant_types (name, description, watering_habits) VALUES
('calathea',
 'Calathea is a tropical foliage plant prized for its boldly patterned leaves that fold up at night. It thrives in warm, humid rooms with bright indirect light and resents direct sun, which scorches the leaves. It is a touch fussy about water quality and consistency, making it a rewarding plant for attentive growers.',
 'Keep the soil lightly and evenly moist at all times — never bone dry, never soggy. Water when the top centimetre starts to dry, using room-temperature filtered or rainwater since it is sensitive to the minerals in tap water. Reduce slightly in winter but do not let it dry out fully.'),
('monstera',
 'Monstera deliciosa is a vigorous tropical climber known for its large, glossy leaves that develop dramatic splits and holes as they mature. It is forgiving and fast-growing, making it a popular statement houseplant. Give it bright indirect light and room to climb for the biggest, most fenestrated leaves.',
 'Let the top few centimetres of soil dry out between waterings, then water thoroughly until it drains. It prefers to dry out a bit more than a calathea and is prone to root rot if kept constantly wet. Water roughly weekly in summer and every two to three weeks in winter.')
ON CONFLICT (name) DO UPDATE
  SET description = EXCLUDED.description,
      watering_habits = EXCLUDED.watering_habits;

-- Two plants. Calathea uses the wetter calathea-specific thresholds
-- (44000 / 39000 / 33000); monstera uses the generic defaults.
INSERT INTO plants (name, plant_type, threshold_dry, threshold_getting_dry, threshold_too_wet)
VALUES
('Bladverk Calathea', 'calathea', 44000, 39000, 33000),
('Fönster Monstera',  'monstera', 47000, 40000, 32000);

-- Hourly readings for the last 7 days: a sawtooth that dries out (rises) over
-- ~2-day cycles and drops at each watering. Lands around 33500 (Happy) now.
INSERT INTO readings (plant_id, moisture_raw, recorded_at)
SELECT (SELECT id FROM plants WHERE name = 'Bladverk Calathea'),
       (33500
        + mod((extract(epoch FROM (now() - g)) / 3600)::int, 48) * 230
        + (random() * 700 - 350))::int,
       g
FROM generate_series(now() - interval '7 days', now(), interval '1 hour') AS g;

-- Monstera: drier regime, ~3-day cycles, sits around 40000 (Getting dry) now.
INSERT INTO readings (plant_id, moisture_raw, recorded_at)
SELECT (SELECT id FROM plants WHERE name = 'Fönster Monstera'),
       (40000
        + mod((extract(epoch FROM (now() - g)) / 3600)::int, 72) * 120
        + (random() * 600 - 300))::int,
       g
FROM generate_series(now() - interval '5 days', now(), interval '1 hour') AS g;

-- Watering events aligned with the sawtooth lows so the chart overlay lines up.
INSERT INTO waterings (plant_id, watered_at)
SELECT (SELECT id FROM plants WHERE name = 'Bladverk Calathea'), w
FROM (VALUES
    (now() - interval '6 days'),
    (now() - interval '4 days'),
    (now() - interval '2 days')
) AS t(w);

INSERT INTO waterings (plant_id, watered_at)
SELECT (SELECT id FROM plants WHERE name = 'Fönster Monstera'), w
FROM (VALUES
    (now() - interval '3 days')
) AS t(w);
